def calculate_average_temperature(data):
    """
    Given a list of tuples representing temperature readings at different locations, 
    calculate the average temperature for each location.

    Args:
    data (list): A list of tuples in the form (location, temperature).

    Returns:
    dict: A dictionary mapping each location to its average temperature.
    """

### Solution:

    location_temperatures = {}
    for location, temperature in data:
        if location not in location_temperatures:
            location_temperatures[location] = []
        location_temperatures[location].append(temperature)

    average_temperatures = {}
    for location, temperatures in location_temperatures.items():
        average_temperatures[location] = sum(temperatures) / len(temperatures)

    return average_temperatures

### Problem:
def dictionary_shift(dictionary, num_shifts):
    """
    Takes a dictionary as input and performs left and right shift operations on it based on the given number of shifts.

    Args:
        dictionary (dict): The dictionary to be shifted.
        num_shifts (int): The number of times the dictionary should be shifted left or right.

    Returns:
        dict: The shifted dictionary.
    """

### Solution:

    for _ in range(abs(num_shifts)):
        if num_shifts < 0:
            dictionary = {k: dictionary.get([k for k in dictionary.keys()][i + 1]) for i, k in enumerate(dictionary.keys()) if i + 1 < len(dictionary)}
        else:
            dictionary = {k: dictionary.get([k for k in dictionary.keys()][i - 1]) for i, k in enumerate(dictionary.keys()) if i > 0}
    return dictionary

