        if type(input_data) == list:
            return input_data
        elif type(input_data) == set:
            return list(input_data)
        elif type(input_data) == tuple:
            return list(input_data)
        elif type(input_data) == dict:
            return list(input_data.values())
        else:
            return []

    elif conversion_type == 'set':
        if type(input_data) == set:
            return input_data
        elif type(input_data) == list:
            return set(input_data)
        elif type(input_data) == tuple:
            return set(input_data)

