def most_common_subject(photos, subject):
    """
    Given a list of photos and a subject, find the photo with the most common subject.

    Args:
    - photos (list): A list of dictionaries representing photos. Each dictionary contains the following keys:
        - 'id' (int): The unique identifier of the photo.
        - 'subjects' (list): A list of subjects captured in the photo.
    - subject (str): The subject to search for among the photos.

    Returns:
    - (dict) The photo with the most common subject. The dictionary contains the following keys:
        - 'id' (int): The unique identifier of the photo.
        - 'subjects' (list): A list of subjects captured in the photo.
    """

### Solution:

    photo_counts = {}
    for photo in photos:
        if subject in photo['subjects']:
            if photo_counts.get(photo['id']):
                photo_counts[photo['id']] += 1
            else:
                photo_counts[photo['id']] = 1

    max_photo_id = max(photo_counts, key=lambda k: photo_counts[k])
    for photo in photos:
        if photo['id'] == max_photo_id:
            return photo

