    >>> count_animals([['lion', 'tiger'], ['elephant', 'rhino'], ['lion', 'lion']])
    {'lion': 3, 'tiger': 1, 'elephant': 1, 'rhino': 1}
    """

### Solution:

    animal_count = {}

    for group in animal_list:
        for animal in group:
            if animal in animal_count:
                animal_count[animal] += 1
            else:
                animal_count[animal] = 1

    return animal_count

