    >>> count_bases("CCCCCCCC")
    {'A': 0, 'T': 0, 'C': 8, 'G': 0}
    """

### Solution:


    base_counts = {}
    for base in sequence:
        if base == "A" or base == "T" or base == "C" or base == "G":
            if base in base_counts:
