    Returns:
    dict: A modified dictionary where each value is multiplied by its corresponding key.
    """

### Solution:

    for operation, value in dictionary.items():
        if isinstance(value, int):
            if operation == "+":
                value += dictionary.get(operation, 0)
            elif operation == "-":
                value -= dictionary.get(operation, 0)
            elif operation == "*":
                value *= dictionary.get(operation, 1)
            elif operation == "/":
                value /= dictionary.get(operation, 1)
            elif operation == "%":
                value %= dictionary.get(operation, 1)
            elif operation == "**":
                value **= dictionary.get(operation, 1)
        dictionary[operation] = value

    return dictionary

