    """
    The function takes a list of sequences and counts the number of repetitions in each sequence.

    Args:
    sequences: a list of sequences (string or integers)

    Returns:
    A dictionary with the count of repetitions for each sequence
    """

### Solution:

    repetitions = {}
    for sequence in sequences:
        if isinstance(sequence, str):
            repetitions[sequence] = len([char for char in sequence if char.isalpha()]) - len(set(sequence))
        elif isinstance(sequence, int):
            repetitions[sequence] = len([digit for digit in str(sequence)]) - len(set(str(sequence))))
        else:
            repetitions[sequence] = None
    return repetitions


