def calculate_total_cost(rooms):

    """
    Given a nested dictionary representing the cost of different materials and labor for each room,
    calculate the total cost of all the rooms combined.

    The format of the dictionary is as follows:
    {
        room1: {
            'materials': {
                'material1': cost1,
                'material2': cost2,
                ...
