                'material4': cost5,
                ...
            },
            'labor': cost6
        },
        ...
    }

    Returns:
    An integer representing the total cost of all the rooms combined.
    """

### Solution:


    total_cost = 0

    for room in rooms:
        material_cost = sum(rooms[room]['materials'].values())
        labor_cost = rooms[room]['labor']
        room_cost = material_cost + labor_cost
        total_cost += room_cost

    return total_cost

