def find_missing_values(data):

    """This function takes a nested dictionary as input and finds the missing values in the range of negative integers from -100 to -1.

    Args:
    - data (dict): Input nested dictionary

    Returns:
    - missing_values (list): List of missing values in the range of -100 to -1

    """

### Solution:


    missing_values = []  # Initialize an empty list to store the missing values

