                            if tag in sg['tags']:
                                ret['changes']['old']['tags'][tag] = sg['tags'][tag]
        if not tags_to_update and not tags_to_remove and not tags_to_add:
            ret['comment'] = ' '.join([ret['comment'], 'Tags are already set.'])
