                            version['name'],
                        ))
                        data[name] = {
                            'publisher': publisher,
                            'offer': offer['name'],
                            'sku': sku['name'],
                            'version': version['name'],
                        }
        except CloudError as exc:
            __utils__['azurearm.log_cloud_error']('compute', exc.message)
            data = {publisher: exc.message}

        return data

    try:
        publishers_query = compconn.virtual_machine_images.list_publishers(
